<?php
namespace App\Http\Controllers\MasterData;
use App\Models\Vendor;
class VendorController extends AbstractMasterController {
 protected string $modelClass=Vendor::class; protected string $menuCode='master.vendors'; protected string $title='Vendors'; protected array $columns=['code'=>'Code','name'=>'Name','email'=>'Email','payment_term_days'=>'Payment Term']; protected array $fields=['code'=>['label'=>'Code','type'=>'text'],'name'=>['label'=>'Name','type'=>'text'],'address'=>['label'=>'Address','type'=>'textarea'],'city'=>['label'=>'City','type'=>'text'],'state'=>['label'=>'State','type'=>'text'],'country'=>['label'=>'Country','type'=>'text'],'phone'=>['label'=>'Phone','type'=>'text'],'email'=>['label'=>'Email','type'=>'email'],'npwp'=>['label'=>'NPWP','type'=>'text'],'payment_term_days'=>['label'=>'Payment Term (Days)','type'=>'number'],'credit_limit'=>['label'=>'Credit Limit','type'=>'number','step'=>'0.0001'],'bank_name'=>['label'=>'Bank Name','type'=>'text'],'bank_account_no'=>['label'=>'Bank Account No','type'=>'text'],'account_owner'=>['label'=>'Account Owner','type'=>'text'],'vendor_posting_group_id'=>['label'=>'Vendor Posting Group','type'=>'select','options'=>'vendor_groups','nullable'=>true],'tax_posting_group_id'=>['label'=>'Tax Posting Group','type'=>'select','options'=>'tax_groups','nullable'=>true],'payable_account_id'=>['label'=>'Payable Account (fallback)','type'=>'select','options'=>'accounts','nullable'=>true],'is_active'=>['label'=>'Active','type'=>'checkbox']];
 protected function rules(?int $id=null): array{return ['code'=>$this->uniqueCode($id),'name'=>['required','string','max:255'],'address'=>['nullable','string'],'city'=>['nullable','string','max:255'],'state'=>['nullable','string','max:255'],'country'=>['nullable','string','max:255'],'phone'=>['nullable','string','max:50'],'email'=>['nullable','email','max:255'],'npwp'=>['nullable','string','max:80'],'payment_term_days'=>['required','integer','min:0'],'credit_limit'=>['required','numeric','min:0'],'bank_name'=>['nullable','string','max:255'],'bank_account_no'=>['nullable','string','max:255'],'account_owner'=>['nullable','string','max:255'],'vendor_posting_group_id'=>['nullable','exists:vendor_posting_groups,id'],'tax_posting_group_id'=>['nullable','exists:tax_posting_groups,id'],'payable_account_id'=>['nullable','exists:chart_of_accounts,id'],'is_active'=>['required','boolean']];}
 protected function options(): array{return ['accounts'=>\App\Models\ChartOfAccount::where('is_active',true)->where('allow_posting',true)->orderBy('code')->get()->mapWithKeys(fn($a)=>[$a->id=>$a->code.' - '.$a->name]),'vendor_groups'=>\App\Models\VendorPostingGroup::where('is_active',true)->orderBy('code')->get()->mapWithKeys(fn($g)=>[$g->id=>$g->code.' - '.$g->name]),'tax_groups'=>\App\Models\TaxPostingGroup::where('is_active',true)->orderBy('code')->get()->mapWithKeys(fn($g)=>[$g->id=>$g->code.' - '.$g->name])];}
}
